\"\"\"Unit tests for openai_client module.\"\"\"

import os
import sys

# Set up test environment
os.environ['OPENAI_API_KEY'] = 'test-api-key-123'

import openai_client
from openai_client import (
    OpenAIResponsesClient,
    send_prompt,
    APIRequestError,
    APIResponseError,
)


class TestOpenAIResponsesClient:
    \"\"\"Tests for OpenAIResponsesClient class.\"\"\"

    def test_default_values(self):
        \"\"\"Test that default values are set correctly.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        assert client.api_key == 'test-key'
        assert client.model == OpenAIResponsesClient.DEFAULT_MODEL
        assert client.timeout == OpenAIResponsesClient.DEFAULT_TIMEOUT
        assert client.API_HOST == 'api.openai.com'
        assert client.API_PATH == '/v1/responses'

    def test_custom_model_and_timeout(self):
        \"\"\"Test custom model and timeout.\"\"\"
        client = OpenAIResponsesClient(
            api_key='[REDACTED_SECRET]',
            model='gpt-4-turbo',
            timeout=60,
        )
        assert client.model == 'gpt-4-turbo'
        assert client.timeout == 60

    def test_env_var_fallback(self):
        \"\"\"Test that env var is used when api_key not provided.\"\"\"
        # Reset and test with env var
        if 'OPENAI_API_KEY' in os.environ:
            del os.environ['OPENAI_API_KEY']
        os.environ['OPENAI_API_KEY'] = 'env-var-key'

        # Need to pass something to trigger env var lookup
        client = OpenAIResponsesClient(api_key=[REDACTED_SECRET]'OPENAI_API_KEY'])
        assert client.api_key == 'env-var-key'

    def test_empty_api_key_raises(self):
        \"\"\"Test that empty API key raises ValueError.\"\"\"
        if 'OPENAI_API_KEY' in os.environ:
            del os.environ['OPENAI_API_KEY']

        try:
            OpenAIResponsesClient(api_key='')
            assert False, \"Should have raised ValueError\"
        except ValueError as e:
            assert 'API key' in str(e)

    def test_build_payload_basic(self):
        \"\"\"Test basic payload building.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        payload = client._build_payload('Hello world')

        assert payload['model'] == client.DEFAULT_MODEL
        assert 'instructions' not in payload
        assert len(payload['input']) == 1
        assert payload['input'][0]['role'] == 'user'
        assert payload['input'][0]['content'][0]['type'] == 'input_text'
        assert payload['input'][0]['content'][0]['text'] == 'Hello world'

    def test_build_payload_with_system_message(self):
        \"\"\"Test payload building with system message.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        payload = client._build_payload('Hello', system_message='You are helpful')

        assert payload['instructions'] == 'You are helpful'
        assert len(payload['input']) == 1

    def test_get_response_text_simple(self):
        \"\"\"Test extracting text from simple response.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        response = {
            'id': 'resp_123',
            'output': [
                {
                    'type': 'message',
                    'content': [
                        {'type': 'output_text', 'text': 'Hello"'!'"'}
                    ]
                }
            ]
        }
        assert client.get_response_text(response) == 'Hello"'!'"'

    def test_get_response_text_multiple_parts(self):
        \"\"\"Test extracting text from multi-part response.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        response = {
            'output': [
                {
                    'type': 'message',
                    'content': [
                        {'type': 'output_text', 'text': 'Part 1'},
                        {'type': 'output_text', 'text': 'Part 2'}
                    ]
                }
            ]
        }
        assert client.get_response_text(response) == 'Part 1Part 2'

    def test_get_response_text_skips_reasoning(self):
        \"\"\"Test that reasoning output is skipped.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        response = {
            'output': [
                {'type': 'reasoning', 'summary': 'thinking...'},
                {
                    'type': 'message',
                    'content': [
                        {'type': 'output_text', 'text': 'Answer'}
                    ]
                }
            ]
        }
        assert client.get_response_text(response) == 'Answer'

    def test_get_response_text_empty_output(self):
        \"\"\"Test with empty output.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        response = {'output': []}
        assert client.get_response_text(response) == ''

    def test_get_response_text_no_output_key(self):
        \"\"\"Test with no output key.\"\"\"
        client = OpenAIResponsesClient(api_key='[REDACTED_SECRET]')
        response = {'id': 'abc'}
        assert client.get_response_text(response) == ''


class TestErrorClasses:
    \"\"\"Tests for error exception classes.\"\"\"

    def test_api_request_error(self):
        \"\"\"Test APIRequestError.\"\"\"
        try:
            raise APIRequestError('connection failed')
        except APIRequestError as e:
            assert str(e) == 'connection failed'

    def test_api_response_error(self):
        \"\"\"Test APIResponseError.\"\"\"
        error = APIResponseError(
            'bad request',
            status_code=400,
            details={'error': 'invalid'}
        )
        assert error.message == 'bad request'
        assert error.status_code == 400
        assert error.details == {'error': 'invalid'}
        assert '400' in str(error)


class TestSendPromptFunction:
    \"\"\"Tests for convenience send_prompt function.\"\"\"

    def test_signature(self):
        \"\"\"Test function signature.\"\"\"
        import inspect
        sig = inspect.signature(send_prompt)
        params = list(sig.parameters.keys())
        assert params == ['prompt', 'api_key', 'model', 'system_message']


if __name__ == '__main__':
    # Run tests
    test_classes = [
        TestOpenAIResponsesClient,
        TestErrorClasses,
        TestSendPromptFunction,
    ]

    passed = 0
    failed = 0

    for test_class in test_classes:
        instance = test_class()
        for method_name in dir(instance):
            if method_name.startswith('test_'):
                method = getattr(instance, method_name)
                try:
                    method()
                    print(f\"✓ {test_class.__name__}.{method_name}\")
                    passed += 1
                except AssertionError as e:
                    print(f\"✗ {test_class.__name__}.{method_name}: {e}\")
                    failed += 1
                except Exception as e:
                    print(f\"✗ {test_class.__name__}.{method_name}: {type(e).__name__}: {e}\")
                    failed += 1

    print()
    print(f\"Results: {passed} passed, {failed} failed\")
    sys.exit(0 if failed == 0 else 1)
